declare
  v_class jsonb;
  v_envelope jsonb;
  v_stored_fingerprint text;
  v_recomputed_fingerprint text;
begin
  v_class := public._ctms_import_correction_classify_v1(p_timesheet_id);

  if coalesce((v_class ->> 'is_import_authoritative_correction')::boolean, false) is not true then
    return null;
  end if;

  select coalesce(
    ts.candidate_hint_text -> 'correction_financials_policy_envelope',
    tf.policy_snapshot_json -> 'correction_financials_policy_envelope',
    tf.rate_source_refs_json -> 'correction_financials_policy_envelope'
  )
  into v_envelope
  from public.timesheets ts
  left join public.timesheets_financials tf
    on tf.timesheet_id = ts.timesheet_id
   and tf.is_current = true
  where ts.timesheet_id = p_timesheet_id;

  if jsonb_typeof(v_envelope) <> 'object' then
    raise exception 'IMPORT_CORRECTION_POLICY_ENVELOPE_MISSING'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'IMPORT_CORRECTION_POLICY_ENVELOPE_MISSING',
              'timesheet_id', p_timesheet_id
            )::text;
  end if;

  v_stored_fingerprint := nullif(btrim(v_envelope ->> 'envelope_fingerprint'), '');
  v_recomputed_fingerprint := encode(
    extensions.digest(
      convert_to((v_envelope - 'envelope_fingerprint')::text, 'UTF8'),
      'sha256'::text
    ),
    'hex'
  );

  if v_stored_fingerprint is null
     or v_stored_fingerprint is distinct from v_recomputed_fingerprint then
    raise exception 'IMPORT_CORRECTION_POLICY_ENVELOPE_FINGERPRINT_INVALID'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'IMPORT_CORRECTION_POLICY_ENVELOPE_FINGERPRINT_INVALID',
              'timesheet_id', p_timesheet_id,
              'stored_fingerprint', v_stored_fingerprint,
              'recomputed_fingerprint', v_recomputed_fingerprint
            )::text;
  end if;

  return v_envelope;
end;

declare
  v_kind text;
  v_envelope jsonb;
  v_leg jsonb;
  v_tsfin_policy jsonb;
  v_invoice_policy jsonb;
begin
  select upper(btrim(coalesce(ts.correction_kind, '')))
  into v_kind
  from public.timesheets ts
  where ts.timesheet_id = p_timesheet_id;

  v_envelope := public._ctms_correction_policy_envelope_read_v1(p_timesheet_id);
  if v_envelope is null then
    return null;
  end if;

  v_leg := case
    when v_kind in ('CHANGED_HOURS_REVERSAL', 'CANCELLATION_REVERSAL')
      then v_envelope -> 'reversal'
    when v_kind in ('CHANGED_HOURS_REPLACEMENT', 'CANCELLATION_REPLACEMENT')
      then v_envelope -> 'replacement'
    else null
  end;

  if jsonb_typeof(v_leg) <> 'object' then
    raise exception 'IMPORT_CORRECTION_POLICY_LEG_MISSING'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'IMPORT_CORRECTION_POLICY_LEG_MISSING',
              'timesheet_id', p_timesheet_id,
              'correction_kind', v_kind
            )::text;
  end if;

  if nullif(v_leg ->> 'leg_fingerprint', '') is null
     or nullif(v_leg ->> 'leg_fingerprint', '') is distinct from encode(
       extensions.digest(
         convert_to((v_leg - 'leg_fingerprint')::text, 'UTF8'),
         'sha256'::text
       ),
       'hex'
     ) then
    raise exception 'IMPORT_CORRECTION_POLICY_LEG_FINGERPRINT_INVALID'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'IMPORT_CORRECTION_POLICY_LEG_FINGERPRINT_INVALID',
              'timesheet_id', p_timesheet_id,
              'correction_kind', v_kind
            )::text;
  end if;

  v_tsfin_policy := v_leg -> 'tsfin_policy';
  v_invoice_policy := v_leg -> 'invoice_policy';
  if jsonb_typeof(v_tsfin_policy) <> 'object'
     or nullif(v_tsfin_policy ->> 'tsfin_policy_fingerprint','') is distinct from encode(
       extensions.digest(
         convert_to((v_tsfin_policy - 'tsfin_policy_fingerprint')::text,'UTF8'),
         'sha256'::text
       ),'hex'
     ) then
    raise exception 'IMPORT_CORRECTION_TSFIN_SUBPOLICY_FINGERPRINT_INVALID'
      using errcode = 'P0001',
            detail = jsonb_build_object('timesheet_id',p_timesheet_id,'correction_kind',v_kind)::text;
  end if;
  if jsonb_typeof(v_invoice_policy) <> 'object'
     or nullif(v_invoice_policy ->> 'invoice_policy_fingerprint','') is distinct from encode(
       extensions.digest(
         convert_to((v_invoice_policy - 'invoice_policy_fingerprint')::text,'UTF8'),
         'sha256'::text
       ),'hex'
     )
     or v_invoice_policy ->> 'invoice_stream' is distinct from v_envelope ->> 'invoice_stream' then
    raise exception 'IMPORT_CORRECTION_INVOICE_SUBPOLICY_FINGERPRINT_INVALID'
      using errcode = 'P0001',
            detail = jsonb_build_object('timesheet_id',p_timesheet_id,'correction_kind',v_kind)::text;
  end if;

  return v_leg || jsonb_build_object(
    'envelope_fingerprint', v_envelope ->> 'envelope_fingerprint',
    'correction_shape', v_envelope ->> 'correction_shape',
    'correction_chain_id', v_envelope ->> 'correction_chain_id',
    'operation_id', v_envelope #>> '{operation,operation_id}',
    'invoice_stream', v_envelope ->> 'invoice_stream'
  );
end;

declare
  r_ts record;
  r_seg record;

  v_tf_mode text;
  v_segments_json jsonb;
  v_sched_json jsonb;

  v_idx int;
  v_start_local text;
  v_end_local text;

  v_seg_id_local text;
  v_emitted int := 0;
begin
  if p_timesheet_id is null then
    raise exception 'timesheet_id is required';
  end if;

  -- Load the timesheet + current TSFIN snapshot (for SEGMENTS-mode refs when applicable)
  select
    ts.timesheet_id as ts_id,
    ts.sheet_scope as ts_sheet_scope,
    ts.submission_mode as ts_submission_mode,
    ts.reference_number as ts_reference_number,
    ts.week_ending_date as ts_week_ending_date,
    ts.worked_start_iso as ts_worked_start_iso,
    ts.worked_end_iso as ts_worked_end_iso,
    ts.scheduled_start_iso as ts_scheduled_start_iso,
    ts.scheduled_end_iso as ts_scheduled_end_iso,
    ts.actual_schedule_json as ts_actual_schedule_json,
    tf.invoice_breakdown_json as tf_invoice_breakdown_json
  into r_ts
  from public.timesheets ts
  left join public.timesheets_financials tf
    on tf.timesheet_id = ts.timesheet_id
   and tf.is_current = true
  where ts.timesheet_id = p_timesheet_id
  limit 1;

  if not found then
    return;
  end if;

  v_tf_mode := upper(coalesce(r_ts.tf_invoice_breakdown_json->>'mode',''));
  v_segments_json := r_ts.tf_invoice_breakdown_json->'segments';
  v_sched_json := r_ts.ts_actual_schedule_json;

  -- ------------------------------------------------------------
  -- A) SEGMENTS mode (NHSP/HR/etc): derive SEGMENT rows from TSFIN segments
  -- ------------------------------------------------------------
  if v_tf_mode = 'SEGMENTS'
     and jsonb_typeof(v_segments_json) = 'array'
  then
    for r_seg in
      select value as seg
      from jsonb_array_elements(v_segments_json) value
    loop
      if r_seg.seg is null or jsonb_typeof(r_seg.seg) <> 'object' then
        continue;
      end if;

      timesheet_id := r_ts.ts_id;
      sheet_scope := r_ts.ts_sheet_scope::text;
      submission_mode := r_ts.ts_submission_mode::text;
      ref_target := 'SEGMENT';

      day_ymd := nullif(btrim(coalesce(r_seg.seg->>'date','')), '');
      start_utc := nullif(btrim(coalesce(r_seg.seg->>'start_utc','')), '');
      end_utc := nullif(btrim(coalesce(r_seg.seg->>'end_utc','')), '');

      if day_ymd is null and start_utc is not null then
        begin
          day_ymd := (((start_utc::timestamptz) at time zone 'Europe/London')::date)::text;
        exception when others then
          day_ymd := null;
        end;
      end if;

      v_seg_id_local := nullif(btrim(coalesce(r_seg.seg->>'segment_id','')), '');
      segment_id := v_seg_id_local;

      if segment_id is null and start_utc is not null and end_utc is not null then
        segment_id := 'SE:' || start_utc || '|' || end_utc;
      end if;

      current_reference := nullif(btrim(coalesce(r_seg.seg->>'ref_num','')), '');

      row_key := r_ts.ts_id::text
        || '|' || coalesce(ref_target,'')
        || '|' || coalesce(segment_id,'')
        || '|' || coalesce(day_ymd,'')
        || '|' || coalesce(start_utc,'')
        || '|' || coalesce(end_utc,'');

      v_emitted := v_emitted + 1;
      return next;
    end loop;

    if v_emitted > 0 then
      return;
    end if;
  end if;

  -- ------------------------------------------------------------
  -- B) WEEKLY schedule-based rows from timesheets.actual_schedule_json
  -- ------------------------------------------------------------
  if r_ts.ts_sheet_scope::text = 'WEEKLY'
     and jsonb_typeof(v_sched_json) = 'array'
  then
    for r_seg in
      select value as seg, ordinality as idx
      from jsonb_array_elements(v_sched_json) with ordinality
    loop
      if r_seg.seg is null or jsonb_typeof(r_seg.seg) <> 'object' then
        continue;
      end if;

      v_start_local := nullif(btrim(coalesce(r_seg.seg->>'start','')), '');
      v_end_local   := nullif(btrim(coalesce(r_seg.seg->>'end','')), '');

      start_utc := nullif(btrim(coalesce(r_seg.seg->>'start_utc','')), '');
      end_utc   := nullif(btrim(coalesce(r_seg.seg->>'end_utc','')), '');

      if (v_start_local is null or v_end_local is null)
         and (start_utc is null or end_utc is null)
      then
        continue;
      end if;

      v_idx := (r_seg.idx - 1);

      timesheet_id := r_ts.ts_id;
      sheet_scope := r_ts.ts_sheet_scope::text;
      submission_mode := r_ts.ts_submission_mode::text;
      ref_target := 'SEGMENT';

      segment_id := nullif(btrim(coalesce(r_seg.seg->>'segment_id','')), '');
      if segment_id is null then
        segment_id := ('ts:' || r_ts.ts_id::text || ':' || v_idx::text);
      end if;

      day_ymd := nullif(btrim(coalesce(r_seg.seg->>'date','')), '');

      if day_ymd is null and start_utc is not null then
        begin
          day_ymd := (((start_utc::timestamptz) at time zone 'Europe/London')::date)::text;
        exception when others then
          day_ymd := null;
        end;
      end if;

      current_reference :=
        nullif(btrim(coalesce(r_seg.seg->>'ref_num','')), '');
      if current_reference is null then
        current_reference := nullif(btrim(coalesce(r_seg.seg->>'booking_ref','')), '');
      end if;

      row_key := r_ts.ts_id::text
        || '|' || coalesce(ref_target,'')
        || '|' || coalesce(segment_id,'')
        || '|' || coalesce(day_ymd,'')
        || '|' || coalesce(start_utc,'')
        || '|' || coalesce(end_utc,'');

      v_emitted := v_emitted + 1;
      return next;
    end loop;

    if v_emitted > 0 then
      return;
    end if;
  end if;

  -- ------------------------------------------------------------
  -- C) DAILY (or any fallback): single timesheet-level reference row
  -- ------------------------------------------------------------
  timesheet_id := r_ts.ts_id;
  sheet_scope := r_ts.ts_sheet_scope::text;
  submission_mode := r_ts.ts_submission_mode::text;
  ref_target := 'TIMESHEET';
  segment_id := null;
  day_ymd := null;

  if r_ts.ts_worked_start_iso is not null then
    day_ymd := ((r_ts.ts_worked_start_iso at time zone 'Europe/London')::date)::text;
  elsif r_ts.ts_scheduled_start_iso is not null then
    day_ymd := ((r_ts.ts_scheduled_start_iso at time zone 'Europe/London')::date)::text;
  elsif r_ts.ts_week_ending_date is not null then
    day_ymd := r_ts.ts_week_ending_date::text;
  end if;

  start_utc := coalesce(
    (to_jsonb(r_ts.ts_worked_start_iso)#>>'{}'),
    (to_jsonb(r_ts.ts_scheduled_start_iso)#>>'{}')
  );
  end_utc := coalesce(
    (to_jsonb(r_ts.ts_worked_end_iso)#>>'{}'),
    (to_jsonb(r_ts.ts_scheduled_end_iso)#>>'{}')
  );
  current_reference := nullif(btrim(coalesce(r_ts.ts_reference_number,'')), '');

  row_key := r_ts.ts_id::text
    || '|' || coalesce(ref_target,'')
    || '|' || coalesce(segment_id,'')
    || '|' || coalesce(day_ymd,'')
    || '|' || coalesce(start_utc,'')
    || '|' || coalesce(end_utc,'');

  return next;
end;

declare
  v_raw_sig text;
  v_sig text;
begin
  if p_timesheet_id is null then
    return null;
  end if;

  select
    coalesce(
      string_agg(
        (r.row_key || '=' || coalesce(r.current_reference, '')),
        '||'
        order by r.row_key
      ),
      ''
    )
  into v_raw_sig
  from public.timesheet_pdf_reference_rows(p_timesheet_id) r;

  select
    encode(
      extensions.digest(coalesce(v_raw_sig, ''), 'sha256'),
      'hex'
    )
  into v_sig;

  return v_sig;
end;

declare
  v_contract public.contracts%rowtype;
  v_client public.client_settings%rowtype;
  v_client_record public.clients%rowtype;
  v_defaults public.settings_defaults%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_finance jsonb := '{}'::jsonb;
  v_client_id uuid := p_client_id;
  v_client_found boolean := false;
  v_unresolved_daily boolean := false;
  v_workflow text := upper(btrim(coalesce(p_workflow, '')));
  v_override boolean := false;
  v_is_nhsp boolean := false;
  v_requires_hr boolean := false;
  v_autoprocess_hr boolean := false;
  v_no_timesheet_required boolean := false;
  v_import_authoritative boolean := false;
  v_self_bill boolean := false;
  v_configuration_valid boolean := true;
  v_configuration_issue text;
  v_route text := 'STANDARD_WEEKLY';
  v_source text := 'CLIENT_SETTINGS';
  v_holidays jsonb := '[]'::jsonb;
  v_values jsonb;
  v_sources jsonb;
  v_components jsonb;
  v_applicability jsonb;
  v_payload jsonb;
  v_fingerprint text;
begin
  if p_relevant_date is null then
    raise exception 'CONTRACT_SETTINGS_RELEVANT_DATE_REQUIRED' using errcode='22023';
  end if;
  if v_workflow not in ('WEEKLY','DAILY','IMPORT','OFFICE','INVOICE','FINANCE') then
    raise exception 'CONTRACT_SETTINGS_WORKFLOW_INVALID' using errcode='22023';
  end if;

  if p_timesheet_id is not null then
    select * into v_timesheet
    from public.timesheets t
    where t.timesheet_id=p_timesheet_id and t.is_current=true;
    if not found then
      raise exception 'CONTRACT_SETTINGS_CURRENT_TIMESHEET_NOT_FOUND' using errcode='P0002';
    end if;
    if v_timesheet.settings_authority_json <> '{}'::jsonb then
      return private._timesheet_settings_authority_frozen_v1(p_timesheet_id);
    end if;
    if v_timesheet.sheet_scope='WEEKLY'::public.timesheet_scope_enum
       or exists(
         select 1 from public.timesheets_financials tf
         where tf.timesheet_id=v_timesheet.timesheet_id
           and tf.is_current=true
           and tf.processed_at_utc is not null
       ) then
      raise exception 'CONTRACT_SETTINGS_TIMESHEET_AUTHORITY_NOT_FROZEN' using errcode='55000';
    end if;
    if p_contract_id is not null and p_contract_id is distinct from v_timesheet.contract_id then
      raise exception 'CONTRACT_SETTINGS_TIMESHEET_CONTRACT_MISMATCH' using errcode='22023';
    end if;
  end if;

  if p_contract_id is not null then
    select * into v_contract from public.contracts c where c.id=p_contract_id;
    if not found then
      raise exception 'CONTRACT_SETTINGS_CONTRACT_NOT_FOUND' using errcode='P0002';
    end if;
    if v_client_id is not null and v_client_id<>v_contract.client_id then
      raise exception 'CONTRACT_SETTINGS_CLIENT_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    v_client_id:=v_contract.client_id;
    v_override:=coalesce(v_contract.overrideclientsettings,false);
  end if;
  if v_client_id is null then
    v_unresolved_daily:=(
      p_timesheet_id is not null
      and v_workflow='DAILY'
      and v_timesheet.sheet_scope='DAILY'::public.timesheet_scope_enum
      and v_timesheet.contract_id is null
      and v_timesheet.settings_authority_json='{}'::jsonb
    );
    if not v_unresolved_daily then
      raise exception 'CONTRACT_SETTINGS_CLIENT_REQUIRED' using errcode='22023';
    end if;
  else
    select * into v_client_record from public.clients cl where cl.id=v_client_id;
    if not found then
      raise exception 'CONTRACT_SETTINGS_CLIENT_NOT_FOUND' using errcode='P0002';
    end if;

    select * into v_client
    from public.client_settings cs
    where cs.client_id=v_client_id
      and (cs.effective_from is null or cs.effective_from<=p_relevant_date)
    order by cs.effective_from desc nulls last,cs.updated_at desc,cs.id desc
    limit 1;
    v_client_found:=found;
    if not v_client_found then
      raise exception 'CONTRACT_SETTINGS_CLIENT_SETTINGS_NOT_FOUND' using errcode='P0002';
    end if;
  end if;
  select * into v_defaults from public.settings_defaults d where d.id=1;
  if not found then
    raise exception 'CONTRACT_SETTINGS_GLOBAL_SETTINGS_NOT_FOUND' using errcode='P0002';
  end if;
  select to_jsonb(fin) into v_finance
  from public.settings_finance_pick(p_relevant_date) fin
  limit 1;
  v_finance:=coalesce(v_finance,'{}'::jsonb);

  v_is_nhsp:=case when v_override then coalesce(v_contract.is_nhsp,false)
    else coalesce(v_client.is_nhsp,false) end;
  v_requires_hr:=case when v_override then coalesce(v_contract.requires_hr,false)
    else coalesce(v_client.requires_hr,false) end;
  v_autoprocess_hr:=case when v_override then coalesce(v_contract.autoprocess_hr,false)
    else coalesce(v_client.autoprocess_hr,false) end;
  v_no_timesheet_required:=case when v_override then coalesce(v_contract.no_timesheet_required,false)
    else coalesce(v_client.no_timesheet_required,false) end;

  if v_is_nhsp and (v_requires_hr or v_autoprocess_hr or v_no_timesheet_required) then
    v_configuration_valid:=false;
    v_configuration_issue:='MULTIPLE_IMPORT_FAMILIES';
  elsif v_is_nhsp and v_workflow='DAILY' then
    v_configuration_valid:=false;
    v_configuration_issue:='NHSP_WEEKLY_WITH_DAILY_WORKFLOW';
  elsif v_no_timesheet_required and not v_autoprocess_hr then
    v_configuration_valid:=false;
    v_configuration_issue:='AUTHORITATIVE_ROSTER_WITHOUT_AUTOPROCESS';
  elsif v_requires_hr and not v_autoprocess_hr then
    v_configuration_valid:=false;
    v_configuration_issue:='ROSTER_VALIDATION_WITHOUT_AUTOPROCESS';
  elsif v_autoprocess_hr and not v_no_timesheet_required and not v_requires_hr then
    v_configuration_valid:=false;
    v_configuration_issue:='ROSTER_MODE_NOT_SELECTED';
  end if;

  v_route:=case
    when v_is_nhsp then 'DEDICATED_NHSP_WEEKLY'
    when v_autoprocess_hr and v_no_timesheet_required and v_workflow='DAILY' then 'HEALTHROSTER_DAILY_AUTHORITATIVE'
    when v_autoprocess_hr and v_no_timesheet_required then 'HEALTHROSTER_WEEKLY_AUTHORITATIVE'
    when v_autoprocess_hr and v_workflow='DAILY' then 'HEALTHROSTER_DAILY_VALIDATION'
    when v_autoprocess_hr then 'HEALTHROSTER_WEEKLY_VALIDATION'
    when v_workflow='DAILY' then 'STANDARD_DAILY'
    else 'STANDARD_WEEKLY' end;
  v_source:=case
    when v_unresolved_daily then 'UNRESOLVED_DAILY_SAFE'
    when v_override then 'CONTRACT_OVERRIDE'
    else 'CLIENT_SETTINGS' end;
  -- Historical contradictory rows fail safely: they can never grant Candidate
  -- hour entry merely because their old flags disagree.
  v_import_authoritative:=case
    when not v_configuration_valid then v_is_nhsp or v_no_timesheet_required
    else v_is_nhsp or (v_autoprocess_hr and v_no_timesheet_required)
  end;

  -- Self-billing controls expense separation, not Candidate hour-entry authority.
  v_self_bill:=case when v_override then coalesce(v_contract.self_bill,false)
    else coalesce(v_client.self_bill_no_invoices_sent,false) end;

  select coalesce(jsonb_agg(to_jsonb(h.date_value) order by h.date_value),'[]'::jsonb)
  into v_holidays
  from (
    select distinct btrim(x.date_value) date_value
    from (
      select jsonb_array_elements_text(
        case when jsonb_typeof(v_defaults.bh_list)='array' then v_defaults.bh_list else '[]'::jsonb end
      ) date_value
      union all
      select jsonb_array_elements_text(
        case when jsonb_typeof(v_defaults.bh_feed_list)='array' then v_defaults.bh_feed_list else '[]'::jsonb end
      ) date_value
    ) x
    where btrim(x.date_value) ~ '^\d{4}-\d{2}-\d{2}$'
  ) h;

  v_values:=jsonb_build_object(
    'timezone_id',coalesce(v_client.timezone_id,v_defaults.timezone_id,'Europe/London'),
    'day_start',coalesce(v_client.day_start,v_defaults.day_start),
    'day_end',coalesce(v_client.day_end,v_defaults.day_end),
    'night_start',coalesce(v_client.night_start,v_defaults.night_start),
    'night_end',coalesce(v_client.night_end,v_defaults.night_end),
    'sat_start',coalesce(v_client.sat_start,v_defaults.sat_start),
    'sat_end',coalesce(v_client.sat_end,v_defaults.sat_end),
    'sun_start',coalesce(v_client.sun_start,v_defaults.sun_start),
    'sun_end',coalesce(v_client.sun_end,v_defaults.sun_end),
    'bh_start',coalesce(v_client.bh_start,v_defaults.bh_start),
    'bh_end',coalesce(v_client.bh_end,v_defaults.bh_end),
    'bh_list',v_holidays,
    'vat_rate_pct',coalesce(v_client.vat_rate_pct,(v_finance->>'vat_rate_pct')::numeric,20),
    'holiday_pay_pct',coalesce(v_client.holiday_pay_pct,(v_finance->>'holiday_pay_pct')::numeric,12.07),
    'erni_pct',coalesce((v_finance->>'erni_pct')::numeric,13.8),
    'apply_holiday_to',coalesce(v_client.apply_holiday_to,v_finance->>'apply_holiday_to','PAYE_ONLY'),
    'apply_erni_to',coalesce(v_finance->>'apply_erni_to','PAYE_ONLY'),
    'margin_includes',coalesce(v_client.margin_includes,v_finance->'margin_includes','{}'::jsonb),
